#!/usr/bin/env python3
"""Restore the length-16 assignment primal/dual certificate using Python's standard library.
The embedded payload is xz-compressed and base64-encoded for GitHub portability.
Run: python3 lyndon16_restore_dual.py
Then run: python3 lyndon16_verify.py (once witness is restored too).
"""
import base64
import hashlib
import lzma
from pathlib import Path

DATA = """"""
raw = lzma.decompress(base64.b64decode(DATA))
assert hashlib.sha256(raw).hexdigest() == "9103843dff6074b9ce7630c602f5849bb7ba704122cdb7360331d2b126431fee"
dest = Path(__file__).resolve().parent / "lyndon16_matching_dual.json"
dest.write_bytes(raw)
print("Restored:", dest.name, "bytes:", len(raw))
